[{"name":"Update Text From a Slider","description":"This runs `updateThermometer` when the slider value changes.","code":"```
const slider = document.getElementById("temperatureSlider");
const temperatureText = document.getElementById("temperatureText");

const updateThermometer = () => {
  temperatureText.textContent = slider.value;
};

slider.addEventListener("input", updateThermometer);
